function KOVACIC_FIRST_STEP(f):
    d <- degree(f)
    if d < 0:                      # f == 0
        return (SOLVABLE, v = 0)
    if d is odd:
        # parity obstruction: deg(p^2)=2deg p is even,
        # deg(f q^2)=d+2deg q is odd -> no rational solution
        return (OBSTRUCTED, none)
    # d even: seek polynomial v with v' + v^2 = f, deg v = d/2
    for each candidate polynomial v of degree d/2:
        if derivative(v) + v*v == f:
            return (SOLVABLE, v)        # y = exp(integral v)
    return (OBSTRUCTED_OR_HIGHER_CASE, none)

